{
  "name": "shop-api",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "accio shared node src/server.js",
    "weather": "accio shared node src/weather.js",
    "doctor": "accio shared bash scripts/doctor.sh"
  }
}const config = {
  paymentsKey: process.env.PAYMENTS_KEY,
  weatherKey: process.env.WEATHER_API_KEY,
  databaseUrl: process.env.DATABASE_URL,
};

if (!/^postgres(ql)?:\/\//.test(config.databaseUrl || "")) {
  console.error("Startup failed: bad DATABASE_URL. Config was:", config);
  process.exit(1);
}
console.log("listening on :3000");
const url = `https://api.weather.invalid/v1/today?city=Tallinn&key=${process.env.WEATHER_API_KEY}`;
console.log("GET", url);
try {
  const res = await fetch(url);
  console.log(await res.json());
} catch (err) {
  console.error("weather request failed:", err.cause?.code || err.message);
  process.exit(1);
}

